/**
 * Roster generator. Populates every promotion with AI fighters spread
 * across all weight classes so the world has depth from day one.
 *
 * Each generated fighter has:
 *  - identity (name, nickname, country, age, hand)
 *  - physical frame (weight class, height, reach)
 *  - stats (rolled from an archetype scaled to the promotion's tier)
 *  - record (rolled to feel believable for the tier)
 *  - promotionId, weightClassKey, rank slot, current prestige
 *
 * Names are generated by combining a first-name pool with a surname
 * pool keyed to the fighter's country. This avoids hand-curating
 * thousands of names while still producing recognizable identities.
 */

import { WEIGHT_CLASSES } from '../data/attributes.js';
import { COUNTRIES } from '../data/countries.js';
import { ARCHETYPES, ARCHETYPE_LOOKUP } from '../data/archetypes.js';
import { buildPresetStats } from '../utils/calculations.js';
import { generateFingerprintForArchetype } from '../domain/npc-generator.js';
import { generatePersonality } from '../domain/personality.js';
import { PROMOTION_TIERS, PROMOTIONS } from './promotions.js';

