const NICKNAMES = [
    'Night Shift', 'Cold Wire', 'The Lock', 'Switchboard', 'Iron Lung', 'The Saw',
    'Sandman', 'Static', 'The Hammer', 'Vandal', 'The Reaper', 'Bone Saw',
    'Knockout', 'The Wolf', 'Phantom', 'Bulletproof', 'The Architect', 'The Predator',
    'Lights Out', 'The Eagle', 'Highlight', 'The Truth', 'No Mercy', 'The Surgeon',
    'Stone Cold', 'The Outlaw', 'Suga', 'Showtime', 'The Champ', 'Pitbull',
    'Thrill', 'Wonder', 'The Notorious', 'Cowboy', 'Marathon Man', 'King',
    'Steel Toe', 'Pressure', 'The Boa', 'The Last Stand', 'The Bear'
];

function pickRandom(arr, rng = Math.random) {
    return arr[Math.floor(rng() * arr.length)];
}

function generateName(countryCode, rng = Math.random) {
    const first = FIRST_NAMES[countryCode] || FIRST_NAMES.DEFAULT;
    const last = LAST_NAMES[countryCode] || LAST_NAMES.DEFAULT;
    return `${pickRandom(first, rng)} ${pickRandom(last, rng)}`;
}

function generateRecord(tierKey, rng = Math.random) {
    const tier = PROMOTION_TIERS[tierKey] || PROMOTION_TIERS.CIRCUIT;
    const baseFights = tierKey === 'APEX' ? 18
        : tierKey === 'BANNER' ? 14
        : tierKey === 'FRONTIER' ? 10
        : 6;
    const totalFights = Math.max(2, Math.round(baseFights + (rng() * 8 - 2)));
    const winRate = tierKey === 'APEX' ? 0.78
        : tierKey === 'BANNER' ? 0.7
        : tierKey === 'FRONTIER' ? 0.65
        : 0.6;
    const wins = Math.max(1, Math.round(totalFights * (winRate - rng() * 0.15)));
    const losses = Math.max(0, totalFights - wins - Math.round(rng() * 2));
    const draws = Math.max(0, totalFights - wins - losses);
    const finishes = Math.round(wins * (0.4 + rng() * 0.4));
    return { wins, losses, draws, finishes };
}

function pickArchetype(rng = Math.random) {
    return pickRandom(ARCHETYPES, rng);
}

function pickWeightedCountry(rng = Math.random) {
    // Weight toward big MMA-producing nations.
    const weighted = [
        ...Array(20).fill('US'),
        ...Array(8).fill('BR'),
        ...Array(7).fill('RU'),
        ...Array(4).fill('DAG'),
        ...Array(3).fill('GB'),
        ...Array(3).fill('NG'),
        ...Array(3).fill('JP'),
        ...Array(2).fill('TH'),
        ...Array(2).fill('IE'),
        ...Array(2).fill('NL'),
        ...Array(2).fill('KR'),
        ...Array(2).fill('CA'),
        ...Array(2).fill('AU'),
        ...Array(2).fill('MX'),
        ...Array(1).fill('FR'),
        ...Array(1).fill('DE'),
        ...Array(1).fill('PL'),
        ...Array(1).fill('CN')
    ];
    return pickRandom(weighted, rng);
}

/**
 * Generate a single AI fighter for a promotion at a weight class.
 *
 * @returns Fighter record matching the existing roster.js shape, plus
 *          promotion + ranking metadata.
 */
export function generateFighter({
    promotionId,
    weightClassKey,
    rankSlot = null,
    countryCode = null,
    archetypeKey = null,
    rng = Math.random
}) {
    const promo = PROMOTIONS.find(p => p.id === promotionId);
    if (!promo) throw new Error(`Unknown promotion: ${promotionId}`);
    const tier = PROMOTION_TIERS[promo.tier];

    const country = countryCode || pickWeightedCountry(rng);
    const countryRecord = COUNTRIES.find(c => c.code === country) || COUNTRIES[0];
    const archetype = archetypeKey ? ARCHETYPE_LOOKUP[archetypeKey] : pickArchetype(rng);
    const wc = WEIGHT_CLASSES.find(w => w.key === weightClassKey) || WEIGHT_CLASSES[5];

    const overallMod = (tier.prestige - 30) / 12;
    const rankBonus = rankSlot !== null && rankSlot <= 15
        ? (16 - rankSlot) * 0.25
        : 0;

    const baseStats = buildPresetStats(archetype);
    const stats = Object.fromEntries(Object.entries(baseStats).map(([key, value]) => {
        const jitter = Math.round((rng() * 6) - 3);
        const final = Math.round(value + overallMod + rankBonus + jitter);
        return [key, Math.max(15, Math.min(99, final))];
    }));

    const record = generateRecord(promo.tier, rng);
    const age = Math.floor(22 + (record.wins + record.losses) * 0.6 + rng() * 4);
    const height = Math.round(wc.heightMin + rng() * (wc.heightMax - wc.heightMin));
    const reach = Math.round(wc.reachMin + rng() * (wc.reachMax - wc.reachMin));

    const id = `${promo.id}-${weightClassKey}-${Math.floor(rng() * 1_000_000).toString(36)}`;

    return {
        id,
        name: generateName(country, rng),
        nickname: pickRandom(NICKNAMES, rng),
        countryCode: country,
        country: countryRecord,
        archetypeKey: archetype.key,
        archetype,
        weightClassKey,
        weightClass: wc.name,
        promotionId,
        promotionTier: promo.tier,
        rank: rankSlot,
        record,
        difficultyBias: Math.max(0, Math.min(10, Math.round((tier.prestige / 12) + (rankSlot ? (16 - Math.min(rankSlot, 15)) * 0.3 : 0)))),
        overallModifier: Math.round(overallMod),
        hand: rng() < 0.18 ? 'left' : 'right',
        height,
        reach,
        age,
        purse: Math.round(tier.showMoneyMin + rng() * (tier.showMoneyMax - tier.showMoneyMin) * 0.15),
        gymReputation: Math.round(tier.prestige - 10 + rng() * 30),
        stats,
        fingerprint: generateFingerprintForArchetype({ countryCode: country, archetypeKey: archetype.key, rng }),
        personality: generatePersonality(archetype.key),
        titleHolder: false,
        titleDefenses: 0,
        blurb: `${archetype.label} fighting out of ${countryRecord.name}.`
    };
}

/**
 * Populate every promotion with a full roster across all weight
 * classes. Returns a flat array of fighters; callers slice it by
 * promotion + weight class as needed.
 *
 * Roster size per weight class is tier-dependent: APEX gets 24,
 * BANNER 18, FRONTIER 14, CIRCUIT 8 — so a single division has a
 * believable depth chart.
 */
export function generateWorldRoster({ rng = Math.random } = {}) {
    const fighters = [];
    PROMOTIONS.forEach(promo => {
        const tier = PROMOTION_TIERS[promo.tier];
        WEIGHT_CLASSES.forEach(wc => {
            // Super-heavyweight only exists in CIRCUIT/FRONTIER.
            if (wc.key === 'super-heavyweight' && (promo.tier === 'APEX' || promo.tier === 'BANNER')) return;
            // Strawweight has thin depth in lower tiers.
            const rosterSize = wc.key === 'strawweight'
                ? Math.max(4, Math.round(tier.rosterPerWeightClass * 0.6))
                : tier.rosterPerWeightClass;

            for (let i = 0; i < rosterSize; i += 1) {
                const rankSlot = i < 15 ? (i + 1) : null;
                const fighter = generateFighter({
                    promotionId: promo.id,
                    weightClassKey: wc.key,
                    rankSlot,
                    rng
                });
                // The #1 in an APEX/BANNER/FRONTIER division is the
                // reigning champion.
                if (rankSlot === 1 && tier.publishesTop15) {
                    fighter.titleHolder = true;
                    fighter.titleDefenses = Math.floor(rng() * 4);
                }
                fighters.push(fighter);
            }
        });
    });
    return fighters;
}
